<script setup lang="ts">
import { notifyError } from '../notification';
import { onBeforeUnmount as onErrorScopeUnmount } from 'vue';
let errorScope=0,disposed=false;onErrorScopeUnmount(()=>{disposed=true;errorScope++;});
import UiSelect from './UiSelect.vue';

import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { candidateKey, filterCandidates, submitReviewSelection } from '../graphReview';
import { missingHierarchyEdges } from '../graphDisplay';
import { graphLabel } from '../graphLabels';
import ChartView from '../ChartView.vue';
import CandidateEditor from './CandidateEditor.vue';
import { graphApi, type PublishedGraph, type PublishedSource } from '../graphApi';
import type { GraphCandidate, GraphIngestionJob } from '../graphTypes';
const props = defineProps<{ initialJobId?: string; motion: boolean; colors: { text: string; line: string; blue: string; amber: string; teal: string } }>();
const emit = defineEmits<{ published: [version: string] }>();
const jobs = ref<GraphIngestionJob[]>([]), selected = ref<GraphIngestionJob>();
const candidates = ref<GraphCandidate[]>([]), revision = ref(0), published = ref<PublishedGraph>({ nodes: [], edges: [] });
const busy = ref(false), error = ref(''), title = ref(''), rights = ref('CONFIRMED'), targetVersion = ref(''), comment = ref('');
const filterType=ref(''), filterStatus=ref(''), keyword=ref('');
const selection=ref({keys: [] as string[]}), conflict=ref(false), selectionMessage=ref('');
const filteredCandidates=computed(()=>filterCandidates(candidates.value,filterType.value,filterStatus.value,keyword.value));
function toggleCandidate(c: GraphCandidate, checked: boolean) { const key=candidateKey(c); if(checked&&!selection.value.keys.includes(key)) { if(selection.value.keys.length>=100) { selectionMessage.value='每批最多100项，请先审核当前选择。'; return; } selection.value.keys.push(key); } else if(!checked) selection.value.keys=selection.value.keys.filter(k=>k!==key); selectionMessage.value=''; }
function selectFiltered() { const keys=[...new Set([...selection.value.keys,...filteredCandidates.value.map(candidateKey)])]; selection.value.keys=keys.slice(0,100); selectionMessage.value=keys.length>100?'已勾选前100项，请先审核这一批，再处理其余内容。':'已勾选当前筛选结果，请逐项核对来源后提交。'; }
function batchDecide(decision: 'APPROVE'|'REJECT') { void run(async()=>{ try { selected.value=await submitReviewSelection(selection.value,candidates.value,decision,comment.value,decisions=>graphApi.decide(selected.value!.id,revision.value,decisions)); selectionMessage.value='批量审核已保存。'; await loadCandidates(); } catch(e) { if((e as {status?:number}).status===409) { conflict.value=true; selected.value=await graphApi.job(selected.value!.id); await loadCandidates(); throw new Error('审核修订已变化，已重新读取。原选择与意见保留；请核对更新内容，清空后重新勾选再提交。'); } throw e; } }); }
const sourceFile = ref<File>(), mode = ref('candidate'), focused = ref('');
let timer: ReturnType<typeof setTimeout> | undefined;
const terminal = ['WAITING_HUMAN_REVIEW', 'READY_TO_PUBLISH', 'PUBLISHED', 'FAILED', 'CANCELLED', 'PARTIALLY_COMPLETED'];
const payload = (c: GraphCandidate) => c.node || c.edge || c.source;
const canReview = computed(() => !!selected.value && ['WAITING_HUMAN_REVIEW', 'READY_TO_PUBLISH', 'PARTIALLY_COMPLETED'].includes(selected.value.status));
const graphNodes = computed(() => mode.value === 'published' ? published.value.nodes : candidates.value.flatMap(c => c.node ? [c.node] : []));
const graphHeight = computed(() => Math.max(600,Math.min(1000,Math.ceil(graphNodes.value.length/3)*100)));
const nodeName = (id:string) => graphNodes.value.find(n=>n.id===id)?.name || id;
const focusNode = computed(() => graphNodes.value.find(n=>n.id===focused.value));
const editorNodes = computed(() => [...new Map([...published.value.nodes, ...candidates.value.flatMap(c => c.node ? [c.node] : [])].map(n => [n.id, {id:n.id,name:n.name}])).values()]);
async function edited(job: GraphIngestionJob) { selected.value=job; await run(loadCandidates); }
const approvedSources = ref<PublishedSource[]>([]);
const focusSources = computed(() => mode.value==='published' ? approvedSources.value : candidates.value.flatMap(c=>c.source?.nodeId===focused.value?[c.source]:[]));
watch(mode,()=>{ focused.value=''; approvedSources.value=[]; });
function focus(value: unknown) { focused.value=String((value as {data?:{id?:string}}).data?.id||''); approvedSources.value=[]; if(mode.value==='published'&&focused.value) { const id=focused.value; void run(async()=>{ const items=await graphApi.sources(id); if(focused.value===id) approvedSources.value=items; }); } }
const graphEdges = computed(() => mode.value === 'published' ? published.value.edges : candidates.value.flatMap(c => c.edge ? [c.edge] : []));
const option = computed(() => ({ tooltip: { trigger: 'item' }, series: [{ type: 'graph', layout: 'force', roam: true, draggable: true,
  force: { repulsion: 1000, edgeLength: 180, gravity: .05 }, label: { show: true, color: props.colors.text, position: 'bottom', width: 140, overflow: 'truncate' },
  edgeSymbol: ['none', 'arrow'], edgeLabel: { show: false, formatter: '{c}', color: props.colors.text }, emphasis: { focus:'adjacency', edgeLabel:{show:true} }, lineStyle: { color: props.colors.line, width: 2, curveness: .1 },
  data: graphNodes.value.map(n => ({ id: n.id, name: n.name, symbolSize: 32, itemStyle: { color: mode.value === 'published' ? props.colors.teal : props.colors.amber } })),
  links: [
    ...missingHierarchyEdges(graphNodes.value,graphEdges.value).map(e=>({source:e.sourceId,target:e.targetId,value:'包含（层级）',lineStyle:{type:'dashed',color:props.colors.blue,opacity:.55},label:{show:false}})),
    ...graphEdges.value.filter(e => graphNodes.value.some(n => n.id === e.sourceId) && graphNodes.value.some(n => n.id === e.targetId)).map(e => { const rejected='decisionStatus' in e && e.decisionStatus==='REJECTED'; const hierarchy=e.relation==='CONTAINS'; return { source: e.sourceId, target: e.targetId, value: (hierarchy?'包含（层级）':graphLabel(e.relation))+(rejected?'（已拒绝）':''),lineStyle:rejected?{type:'dotted',color:props.colors.line,opacity:.45}:hierarchy?{type:'dashed',color:props.colors.blue,opacity:.55}:{type:'solid',color:props.colors.teal,opacity:.9} }; })
  ]
}] }));
async function run(action: () => Promise<void>) { if (busy.value) return; const errorOpener=document.activeElement instanceof HTMLElement?document.activeElement:null;busy.value = true; error.value = ''; const scope=errorScope;try { await action(); } catch (e) { if(disposed||scope!==errorScope)return;notifyError(e,undefined,errorOpener); error.value = e instanceof Error ? e.message : '请求失败，请重试'; } finally { busy.value = false; } }
async function loadCandidates() {
  if (!selected.value || !selected.value.draftRevision) { candidates.value = []; return; }
  const first = await graphApi.candidates(selected.value.id); const all = [...first.items];
  for (let page = 2; page <= first.totalPages; page++) { const next = await graphApi.candidates(selected.value.id, page); if (next.draftRevision !== first.draftRevision) throw new Error('草稿版本变化，请刷新后复核'); all.push(...next.items); }
  candidates.value = all; revision.value = first.draftRevision;
}
function schedule() { clearTimeout(timer); if (selected.value && !terminal.includes(selected.value.status)) timer = setTimeout(() => { void run(async () => { selected.value = await graphApi.job(selected.value!.id); await loadCandidates(); schedule(); }); }, 3000); }
async function select(id: string) { await run(async () => { selected.value = await graphApi.job(id); focused.value = ''; selection.value.keys=[]; conflict.value=false; selectionMessage.value=''; await loadCandidates(); schedule(); }); }
async function reload() { jobs.value = (await graphApi.jobs()).items; published.value = await graphApi.graph(); }
function upload() { void run(async () => { if (!sourceFile.value || !title.value.trim()) throw new Error('请选择文件并填写教材片段名称'); selected.value = await graphApi.upload(sourceFile.value, title.value.trim(), rights.value); candidates.value = []; await reload(); schedule(); }); }
function decide(c: GraphCandidate, decision: 'APPROVE' | 'REJECT') { void run(async () => { selected.value = await graphApi.decide(selected.value!.id, revision.value, [{ candidateType: c.candidateType, candidateId: c.candidateId, decision, comment: comment.value }]); await loadCandidates(); }); }
function publish() { void run(async () => { if (!targetVersion.value.trim()) throw new Error('请填写目标图谱版本'); selected.value = await graphApi.publish(selected.value!, targetVersion.value.trim()); await reload(); if (selected.value.status === 'PUBLISHED') emit('published', selected.value.publishedGraphVersion!); schedule(); }); }
watch(()=>props.initialJobId,id=>{if(id)void select(id);});
onMounted(async () => { await run(reload); if(props.initialJobId)await select(props.initialJobId); }); onBeforeUnmount(() => clearTimeout(timer));
</script>
<template>
  <section class="kg-workspace">
    <div class="section-title"><div><p class="eyebrow">教材 → 候选 → 人工审核 → 正式图谱</p><h2>知识图谱工作台</h2></div><button :disabled="busy" @click="run(reload)">刷新工作台</button></div>
    <p v-if="error">读取失败，可重试。 <button :disabled="busy" @click="run(async()=>{ await reload(); if(selected) { selected=await graphApi.job(selected.id); await loadCandidates(); schedule(); } })">重新读取</button></p>
    <p v-if="busy" role="status">正在处理，请稍候…</p>
    <form class="card kg-form" @submit.prevent="upload">
      <h3>上传教材片段</h3><p class="muted">TXT / MD / PDF / DOCX。请按章节或片段上传；单批候选数量有限，不代表完成全书。PDF 显示物理页码；扫描件无可提取文本时会失败。教材不写入向量索引。</p>
      <label>片段名称<input v-model="title" required maxlength="200" /></label>
      <label class="file-picker">来源文件<input type="file" accept=".txt,.md,.pdf,.docx" required @change="sourceFile=($event.target as HTMLInputElement).files?.[0]" /></label>
      <UiSelect v-model="rights" label="版权依据" :options="[{value:&#x27;CONFIRMED&#x27;,label:&#x27;已确认使用权&#x27;},{value:&#x27;AUTHORIZED&#x27;,label:&#x27;已获授权&#x27;},{value:&#x27;PUBLIC_DOMAIN&#x27;,label:&#x27;公共领域&#x27;},{value:&#x27;UNKNOWN&#x27;,label:&#x27;尚不明确（受限）&#x27;}]"/>
      <button class="primary" :disabled="busy">上传并开始抽取与模型复核</button>
    </form>
    <section class="card"><h3>抽取任务</h3><p v-if="!jobs.length" class="muted">还没有任务。上传后会在这里显示真实进度。</p><div class="kg-jobs"><button v-for="j in jobs" :key="j.id" :aria-pressed="selected?.id===j.id" :disabled="busy" @click="select(j.id)">{{ j.title }} · {{ graphLabel(j.status) }}<small>节点 {{ j.counts.nodeCount }} / 关系 {{ j.counts.edgeCount }} / 来源 {{ j.counts.sourceCount }} · {{ j.publishedGraphVersion || '尚未发布' }}</small></button></div></section>
    <section v-if="selected" class="card"><h3>{{ selected.title }} · {{ graphLabel(selected.status) }}</h3><p>修订 {{ selected.draftRevision ?? '尚未生成' }} · 已通过 {{ selected.counts.approvedCount }} / 待审 {{ selected.counts.pendingCount }} / 拒绝 {{ selected.counts.rejectedCount }}</p><button v-if="selected.failureMessage" @click="notifyError(selected.failureMessage,'知识处理失败')">查看失败原因</button><button v-if="selected.status==='FAILED'" :disabled="busy" @click="run(async()=>{ selected=await graphApi.retry(selected!.id); schedule(); })">重试抽取</button><div v-if="canReview" class="kg-form"><label>审核意见<input v-model="comment" maxlength="2000" /></label><label>发布版本<input v-model="targetVersion" placeholder="例如 textbook-v1" pattern="[A-Za-z0-9._-]+" /></label><button class="primary" :disabled="busy||selected.status!=='READY_TO_PUBLISH'||!targetVersion" @click="publish">发布已审核内容</button></div><p v-if="selected.publishedGraphVersion">已发布版本 {{ selected.publishedGraphVersion }}</p></section>
    <section class="card"><div class="section-title"><h3>{{ mode==='candidate'?'候选图 · 尚未发布':'正式图 · 已审核发布' }}</h3><UiSelect v-model="mode" label="图谱视图" :options="[{value:&#x27;candidate&#x27;,label:&#x27;当前任务候选&#x27;},{value:&#x27;published&#x27;,label:&#x27;当前课程正式图&#x27;}]"/></div><p class="muted">可拖动节点、缩放和平移。蓝色虚线“包含”展示课程层级，接口未返回时由节点上级 parentId 补充；绿色实线为语义关系。关系文字在悬停时显示。先修箭头起点是先学的知识，终点是依赖它的后续知识。已拒绝的候选关系以灰色点线标明，不属于正式知识。节点和关系也在下方逐项列出。</p><ChartView v-if="graphNodes.length" :option="option" :motion="motion" :height="graphHeight" label="知识节点与关系网络" @select="focus" /><p v-else class="muted">当前视图暂无节点。</p><aside v-if="focusNode" class="kg-candidate" aria-live="polite"><h4>已选：{{ focusNode.name }}</h4><p>{{ focusNode.description }}</p><p class="muted">{{ focusNode.id }}</p><article v-for="source in focusSources" :key="source.id"><strong>{{ source.title }}</strong><p>{{ source.locator }} · 物理页 {{ source.pageFrom ?? '未提供' }}–{{ source.pageTo ?? '未提供' }}</p><blockquote>{{ source.excerpt }}</blockquote></article><p v-if="mode==='candidate'&&!focusSources.length">本节点未关联候选来源，请核对下方逐项审核列表。</p></aside><template v-if="mode==='published'"><details v-for="n in published.nodes" :key="n.id"><summary>{{ n.name }} · {{ n.id }}</summary><p>{{ n.description }}</p><p>层级上级（parentId）：{{ n.parentId || '无' }}</p></details><details v-for="(e,i) in published.edges" :key="i"><summary>{{ nodeName(e.sourceId) }} → {{ graphLabel(e.relation) }} → {{ nodeName(e.targetId) }}</summary><p>起点编号 {{ e.sourceId }} · 终点编号 {{ e.targetId }}</p></details></template></section>
    <section v-if="mode==='candidate' && candidates.length" class="card"><h3>人工逐项审核 · {{ candidates.length }} 条</h3><p class="muted">模型复核不替代人工判断。先核对来源原文、物理页与定位，再审核节点及关系。修订冲突时重新读取后复核。</p><div class="kg-form"><UiSelect v-model="filterType" label="候选类型" :options="[{value:&#x27;&#x27;,label:&#x27;全部类型&#x27;},{value:&#x27;NODE&#x27;,label:&#x27;知识节点&#x27;},{value:&#x27;EDGE&#x27;,label:&#x27;知识关系&#x27;},{value:&#x27;SOURCE&#x27;,label:&#x27;来源证据&#x27;}]"/><UiSelect v-model="filterStatus" label="审核状态" :options="[{value:&#x27;&#x27;,label:&#x27;全部状态&#x27;},{value:&#x27;PENDING&#x27;,label:&#x27;待审核&#x27;},{value:&#x27;APPROVED&#x27;,label:&#x27;人工已批准&#x27;},{value:&#x27;REJECTED&#x27;,label:&#x27;人工已拒绝&#x27;}]"/><label>查找候选<input v-model="keyword" type="search" placeholder="名称、ID、原文或审核问题" /></label></div><p role="status">当前显示 {{ filteredCandidates.length }}/{{ candidates.length }} 项 · 已选 {{ selection.keys.length }}/100 项（含筛选后隐藏的选择）</p><div v-if="canReview" class="kg-batch"><p class="muted">批量前请核对每项的来源、原文和物理页，再填写审核意见。不会自动全选或自动批准。</p><label>批量审核意见<textarea v-model="comment" maxlength="2000" rows="2" placeholder="说明核对依据，批量操作必填" /></label><p v-if="conflict" class="error">版本已冲突，请核对刷新后的条目，并清空原选择后重新勾选。</p><div class="button-row"><button :disabled="busy||conflict||!filteredCandidates.length" @click="selectFiltered">勾选当前筛选结果（最多100项）</button><button :disabled="busy||conflict||!selection.keys.length||!comment.trim()" @click="batchDecide('APPROVE')">批准所选 {{ selection.keys.length }} 项</button><button :disabled="busy||conflict||!selection.keys.length||!comment.trim()" @click="batchDecide('REJECT')">拒绝所选 {{ selection.keys.length }} 项</button><button :disabled="busy" @click="selection.keys=[]; conflict=false; selectionMessage=''">清空选择</button></div><p v-if="selectionMessage" role="status">{{ selectionMessage }}</p></div><p v-if="!filteredCandidates.length" class="muted">没有符合筛选条件的候选，请调整类型、状态或关键词。</p><article v-for="c in filteredCandidates" :key="c.candidateType+c.candidateId" class="kg-candidate" :class="{ 'kg-focused': c.node?.id===focused }"><label v-if="canReview" class="checkbox kg-candidate-check"><input type="checkbox" :checked="selection.keys.includes(candidateKey(c))" :disabled="busy||conflict||(!selection.keys.includes(candidateKey(c))&&selection.keys.length>=100)" @change="toggleCandidate(c,($event.target as HTMLInputElement).checked)" />选择{{ c.node?.name || c.source?.title || c.candidateId }}</label><h4>{{ c.candidateType==='NODE'?'知识节点':c.candidateType==='EDGE'?'知识关系':'来源证据' }} · {{ c.node?.name || c.source?.title || (c.edge?.sourceId+' → '+graphLabel(c.edge?.relation || '')+' → '+c.edge?.targetId) }}</h4><p>{{ graphLabel(c.decisionStatus) }} · 模型分流 {{ graphLabel(c.reviewLane) }} · 提取置信 {{ payload(c)?.extractorConfidence }} / 复核置信 {{ payload(c)?.reviewerConfidence }}</p><template v-if="c.node"><p>{{ c.node.description }}</p><p>ID {{ c.node.id }} · 上级 {{ c.node.parentId || '无' }} · {{ graphLabel(c.node.nodeType) }}</p><p>证据 {{ c.node.evidence.join('；') }}</p></template><p v-if="c.edge">关系原文依据：{{ c.edge.evidence.join('；') }}</p><template v-if="c.source"><p>{{ c.source.locator }} · 物理页 {{ c.source.pageFrom ?? '未提供' }}–{{ c.source.pageTo ?? '未提供' }} · {{ graphLabel(c.source.rightsStatus) }}</p><blockquote>{{ c.source.excerpt }}</blockquote><p>知识点 {{ c.source.nodeId }} · 文件 {{ c.source.fileId }}</p></template><p v-for="(issue,i) in c.validationIssues" :key="i" :class="issue.severity==='ERROR'?'error':'muted'">{{ graphLabel(issue.severity) }} / {{ issue.code }}：{{ issue.message }}</p><p v-if="c.humanReviewComment">人工意见：{{ c.humanReviewComment }}</p><div v-if="canReview" class="button-row"><button :disabled="busy" @click="decide(c,'APPROVE')">批准此项</button><button :disabled="busy" @click="decide(c,'REJECT')">拒绝此项</button></div><CandidateEditor v-if="canReview && selected" :candidate="c" :job-id="selected.id" :revision="revision" :nodes="editorNodes" :disabled="busy" @saved="edited" /></article></section>
  </section>
</template>
